import { createAudioPlayer, setAudioModeAsync, AudioPlayer } from 'expo-audio';

// ============================================================
// Tiny embedded WAV sounds — base64 data URIs, no assets needed.
// ============================================================
const SUCCESS_URI = 'data:audio/wav;base64,';
const ERROR_URI   = 'data:audio/wav;base64,';
const CASH_URI    = 'data:audio/wav;base64,';

export type SoundName = 'success' | 'error' | 'cash';

const _players: Record<SoundName, AudioPlayer | null> = {
  success: null, error: null, cash: null,
};

let _primed = false;

export async function primeSounds(): Promise<void> {
  if (_primed) return;
  _primed = true;
  try {
    await setAudioModeAsync({ playsInSilentMode: true, allowsRecording: false, shouldPlayInBackground: false });
  } catch {}
  try { _players.success = createAudioPlayer({ uri: SUCCESS_URI }); } catch {}
  try { _players.error   = createAudioPlayer({ uri: ERROR_URI   }); } catch {}
  try { _players.cash    = createAudioPlayer({ uri: CASH_URI    }); } catch {}
}

export async function playSound(name: SoundName): Promise<void> {
  const p = _players[name];
  if (!p) return;
  try {
    p.seekTo(0);
    p.play();
  } catch {}
}
